NAME = 'SweKarlXII1873: Svenska Karl XII:s Bibel (1873)'
BOOK = 'Romans'

CHAPTERS = {
    1: {
        1: 'Paulus, Jesu Christi tjenare, kallad till Apostel, afskild till att predika Guds Evangelium;',
        2: 'Hvilket han tillförene utlofvat hafver, genom sina Propheter i den Helga Skrift,',
        3: 'Om sin Son, den född är af Davids säd, efter köttet;',
        4: 'Hvilken är krafteliga bevisad Guds Son, efter Andan som helgar, deraf att han stod upp ifrå de döda, nämliga Jesus Christus, vår Herre;',
        5: 'Genom hvilken vi hafve fått nåd, och Apostlaämbete, till att upprätta trones lydno ibland alla Hedningar, i hans Namn;',
        6: 'Ibland hvilka I ock ären kallade af Jesu Christo;',
        7: 'Allom dem som i Rom äro, Guds kärestom, kalladom heligom. Nåd vare med eder, och frid af Gudi vårom Fader, och Herranom Jesu Christo.',
        8: 'I förstone tackar jag min Gud, gjenom Jesum Christum, för eder alla, att i hela verldene talas om edra tro.',
        9: 'Ty Gud är mitt vittne, hvilkom jag tjenar i minom anda, uti Evangelio som är om hans Son, att jag utan återvändo tänker på eder;',
        10: 'Bedjandes alltid i mina böner, att jag dock någon tid måtte få en lyckosam väg, om Gud ville, till att komma till eder.',
        11: 'Ty jag åstundar se eder, på det jag måtte några andeliga gåfvo dela med eder, till att styrka eder;',
        12: 'Det är, att jag, samt med eder, måtte få hugsvalelse, genom begges våra tro, edra och mina.',
        13: 'Jag vill icke dölja för eder, bröder, att jag hafver ofta haft i sinnet komma till eder, ändock jag hafver varit förhindrad allt härtill; på det jag måtte ock någon frukt skaffa ibland eder, såsom ibland andra Hedningar.',
        14: 'Jag är pligtig både Greker och Barbarer, både visa och ovisa.',
        15: 'Derföre, så mycket mig står till görandes, är jag redebogen att jag ock predikar eder Evangelium, som i Rom ären.',
        16: 'Ty jag skämmes icke vid Christi Evangelium; ty det är Guds kraft allom dem till salighet som tro; Judomen först, så ock Grekomen;',
        17: 'Derföre att derutinnan varder Guds rättfärdighet uppenbar, af tro i tro; som skrifvet är: Den rättfärdige skall lefva af sine tro.',
        18: 'Ty Guds vrede af himmelen varder uppenbar öfver alla menniskornas ogudaktighet och orättfärdighet, de der förhålla sanningena i orättfärdighet.',
        19: 'Ty det, som förstås kan om Gud, är dem uppenbart; ty Gud hafver dem det uppenbarat;',
        20: 'Dermed att hans osynliga väsende, och hans eviga kraft och Gudom varder beskådad, när de besinnas af gerningarna, nämliga af verldenes skapelse; så att de äro utan ursäkt;',
        21: 'Medan de förstodo Gud, och hafva icke prisat honom som en Gud, och ej heller tackat; utan vordo fåfängelige i sina tankar, och deras oförnuftiga hjerta är vordet mörkt.',
        22: 'Då de höllo sig för visa, äro de vordne dårar;',
        23: 'Och hafva förvandlat dens oförgängeliga Guds härlighet uti beläte, det ej allenast gjordt var efter förgängeliga menniskors, utan jemväl efter foglars, och fyrafött och krypande djurs liknelse.',
        24: 'Derföre hafver ock Gud öfvergifvit dem i deras hjertans lustar, uti orenlighet, till att skämma sin lekamen inbördes;',
        25: 'Hvilke förvandlat hafva Guds sanning i lögn; och hafva ärat och dyrkat de ting, som skapad äro, öfver honom som dem skapat hafver, hvilken är välsignad evinnerliga. Amen.',
        26: 'Derföre hafver ock Gud öfvergifvit dem i skamliga lustar; ty deras qvinnor hafva förvandlat den naturliga brukningena uti den, som är emot naturen.',
        27: 'Sammaledes ock männerna hafva öfvergifvit den naturliga qvinnones brukning, och hafva brunnit i sin lusta till hvarannan; man med man bedrifvit slemhet, och fått, som tillbörligit var, deras villos rätta lön i sig sjelfvom.',
        28: 'Och såsom de intet aktade hafva Gud i känslo, hafver Gud öfvergifvit dem i ett vrångt sinne, till att bedrifva obeqvämlig ting;',
        29: 'Fulle med all orättfärdighet, boleri, arghet, girighet, ondsko; fulle med afund, mord, kif, svek, otukt;',
        30: 'Örnatasslare, bakdantare, Guds föraktare, våldsverkare, högfärdige, stolte, illfundige, föräldromen olydige;',
        31: 'Oförnuftige, ordlöse, okärlige, trolöse, obarmhertige;',
        32: 'Hvilke, ändå de Guds rättviso veta, att de som sådant göra äro värde döden, likväl göra de det icke allenast, utan ock hålla med dem som det göra.',
    },
    2: {
        1: 'Derföre äst du utan ursäkt, o menniska, eho du äst som dömer. Ty med det samma du dömer en annan, fördömer du dig sjelf, efter du gör det samma som du dömer.',
        2: 'Ty vi vete, att Guds dom är rätt öfver dem som sådana göra.',
        3: 'Eller menar du, o menniska, som dömer dem som sådana göra, och gör detsamma, att du skall kunna undfly Guds dom?',
        4: 'Eller föraktar du hans godhets, tålsamhets och långmodighets rikedom, icke förståndandes, att Guds mildhet lockar dig till bättring?',
        5: 'Utan efter dina hårdhet och obotfärdiga hjerta samkar du dig sjelfvom vrede, på vredenes dag, när Guds rättvisa dom blifver uppenbar;',
        6: 'Hvilken gifva skall hvarjom och enom efter hans gerningar;',
        7: 'Nämliga pris och äro, och oförgängeligit väsende dem, som med tålamod, uti goda gerningar, fara efter evigt lif.',
        8: 'Men dem som enträtne äro, och icke vilja lyda sanningene, utan lyda orätthetene, ogunst och vrede;',
        9: 'Bedröfvelse och ångest öfver hvar och en menniskos själ, som illa gör; först Judarnas, Grekernas också.',
        10: 'Men heder, och ära, och frid hvarjom och enom som väl gör; först Judomen, Grekomen också.',
        11: 'Ty Gud ser icke efter personen.',
        12: 'Alle de som utan lag syndat hafva, de varda ock utan lag förtappade; och alle som uti lagen hafva syndat, de varda med lagen dömde;',
        13: 'Ty de äro icke rättfärdige för Gudi, som höra lagen; utan de som göra efter lagen, de varda rättfärdige hållne.',
        14: 'Derföre, om Hedningarna, som icke hafva lagen, göra dock af naturen det lagen innehåller; desamme, ändock de icke hafva lagen, äro de likväl sig sjelfvom lag;',
        15: 'Hvilke bevisa lagsens verk vara skrifvet i deras hjertan, der deras samvet bär dem vittne, och deras tankar, som sig inbördes anklaga eller ock ursaka;',
        16: 'På den dagen, när Gud menniskornas lönligheter döma skall, genom Jesum Christum, efter mitt Evangelium.',
        17: 'Si, du kallas en Jude, och förlåter dig på lagen, och berömmer dig af Gudi;',
        18: 'Och vetst hans vilja; och efter du äst undervister i lagen, profvar du hvad bäst är;',
        19: 'Och betröster dig vara en ledare dem som blinde äro, och dem ett ljus som i mörkret äro;',
        20: 'Dem en tuktomästare, som dåraktige äro; dem en lärare, som enfaldige äro; och hafver formen till det som vetandes och rätt är i lagen.',
        21: 'Nu lärer du andra, och lärer dig intet sjelf. Du predikar: Man skall intet stjäla; och du stjäl.',
        22: 'Du säger: Man skall icke göra hor; och du bedrifver hor. Du stygges vid afguderi; och du beröfvar Gudi det honom tillhörer.',
        23: 'Du berömmer dig af lagen, och vanhedrar Gud med lagsens öfverträdning;',
        24: 'Ty för edra skull varder Guds Namn försmädadt ibland Hedningarna, såsom skrifvet är.',
        25: 'Omskärelsen doger, om du håller lagen; men håller du icke lagen, så är din omskärelse vorden en förhud.',
        26: 'Om nu förhuden håller lagsens rättfärdighet, månn icke hans förhud blifva räknad för omskärelse?',
        27: 'Och dermed sker då, att det som af naturen är förhud, och fullkomnar lagen, skall döma dig, som under bokstafven och omskärelsen bryter lagen.',
        28: 'Ty det är icke Jude, som utvärtes är Jude; ej heller det omskärelse, som utvärtes sker på köttet;',
        29: 'Utan det är Jude, som invärtes dolder är; och hjertans omskärelse är omskärelse, den som sker i andanom, och icke efter bokstafven; hvilkens pris icke är af menniskom, utan af Gudi.',
    },
    3: {
        1: 'Hvad fördel hafva då Judarna? Eller hvad är omskärelsen nyttig?',
        2: 'Jo, ganska mycket. Först, att dem hafver varit betrodt det Gud talat hafver.',
        3: 'Hvad magt ligger derpå, att somlige af dem icke trodde? Skulle deras otro göra Guds trohet om intet?',
        4: 'Bort det. Vare heldre Gud sannfärdig, och hvar och en menniska lögnaktig; såsom skrifvet är: På det du blifver rättfärdig i din ord, och öfvervinner, när du dömes.',
        5: 'Är det nu så, att vår orättfärdighet prisar Guds rättfärdighet; hvad vilje vi säga? Är då Gud orättfärdig, som vredgas deröfver? Jag talar efter menniskosätt.',
        6: 'Bort det; ty huru kunde Gud då döma verldena?',
        7: 'Ty om Guds sanning vorde yppare af mine lögn, honom till pris, hvi skulle jag då ännu dömas som en syndare?',
        8: 'Och icke heldre göra, såsom vi vardom försmädde, och som någre säga, att vi skole säga: Låt oss göra ondt, på det der kommer godt af; hvilkas fördömelse är all rätt.',
        9: 'Huru är då derom? Hafve vi någon fördel för dem? Allsingen. Ty vi hafve det nu bevisat, att både Judar och Greker äro alle under synd;',
        10: 'Som skrifvet står: Den är icke till som rättfärdig är; icke en.',
        11: 'Ingen är ock den som förståndig är; ingen är som aktar Gud.',
        12: 'Alle hafva afvikit; allesamman äro onyttige vordne; ingen är som godt gör; icke till en.',
        13: 'Deras strupe är en öppen graf; deras tungor bruka de till svek; huggormaetter under deras läppar.',
        14: 'Deras mun är full med bannor och bitterhet;',
        15: 'Deras fötter snare till att utgjuta blod;',
        16: 'Förtryckelse och vedermöda i deras vägar;',
        17: 'Och fridsens väg veta de icke.',
        18: 'Guds räddhåge är icke för deras ögon.',
        19: 'Så vete vi, att allt det lagen säger, det säger hon till dem som under lagen äro; att hvar och en mun skall tillstoppas, och all verlden skall för Gudi brottslig varda;',
        20: 'Derföre, att intet kött kan af lagsens gerningar varda rättfärdigt för honom; ty af lagen känner man syndena.',
        21: 'Men nu är Guds rättfärdighet, utan lagsens tillhjelp, uppenbar vorden, bevist genom lagen och Propheterna;',
        22: 'Den Guds rättfärdighet, säger jag, som kommer af Jesu Christi tro, till alla, och öfver alla de som tro; ty här är ingen åtskilnad.',
        23: 'Allesamman äro de syndare, och hafva intet berömma sig af för Gudi;',
        24: 'Och varda rättfärdige utan förskyllan, af hans nåd, genom den förlossning som i Christo Jesu skedd är;',
        25: 'Hvilken Gud hafver satt för en nådastol, genom trona i hans blod, i hvilko han låter se sina rättfärdighet, i thy att han förlåter synderna, som blefna voro under Guds tålamod;',
        26: 'Till att låta se i denna tiden sina rättfärdighet; på det han allena skall vara rättfärdig, och göra den rättfärdigan, som är af Jesu tro.',
        27: 'Hvar är nu din berömmelse? Hon är utelyckt. Med hvad lag? Med gerningarnas lag? Nej; utan med trones lag.',
        28: 'Så hålle vi nu det, att menniskan varder rättfärdig af trone, utan lagsens gerningar.',
        29: 'Eller är Gud allenast Judarnas Gud? Är han ock icke Hedningarnas Gud? Jo visserliga, ock Hedningarnas;',
        30: 'Efter det en Gud är, som gör omskärelsen rättfärdig af trone, och förhudena genom trona.',
        31: 'Göre vi då lagen om intet med trone? Bort det; utan vi upprättom lagen.',
    },
    4: {
        1: 'Hvad säge vi då vår fader Abraham efter köttet hafva funnit?',
        2: 'Det säge vi: Är Abraham rättfärdig vorden af gerningarna, så hafver han det han må berömma sig af; men icke för Gudi.',
        3: 'Men hvad säger Skriften? Abraham trodde Gudi, och det vardt honom räknadt till rättfärdighet.',
        4: 'Men honom, som håller sig vid gerningarna, varder lönen icke räknad af nåd, utan af pligt.',
        5: 'Men honom, som icke håller sig vid gerningarna, utan tror på honom som den ogudaktiga gör rättfärdigan, hans tro varder honom räknad till rättfärdighet;',
        6: 'Såsom ock David säger, att saligheten är dens menniskos, hvilko Gud tillräknar rättfärdighetena, utan gerningar.',
        7: 'Salige äro de, som deras orättfärdigheter äro förlåtna, och deras synder äro öfverskylda.',
        8: 'Salig är den man, som Gud ingen synd tillräknar.',
        9: 'Månn nu denna saligheten allenast vara kommen öfver omskärelsen, eller ock öfver förhudena? Vi säge ju, att Abrahe vardt tron räknad till rättfärdighet.',
        10: 'Huru blef hon honom då tillräknad? När han var i omskärelsen, eller när han var i förhudene? Icke i omskärelsen, utan i förhudene.',
        11: 'Men han tog omskärelsens tecken för ett insegel till trones rättfärdighet, hvilka han hade i förhudene; att han skulle vara allas deras fader, som i förhudene trodde, att sådant skulle ock räknas dem för rättfärdighet;',
        12: 'Desslikes ock omskärelsens fader, icke dem allenast, som äro af omskärelsen, utan ock dem som vandra i trones fotspår, som var i vår faders Abrahams förhud.',
        13: 'Ty det löftet, att han skulle varda verldenes arfvinge, är icke skedt Abrahe och hans säd igenom lagen, utan igenom trones rättfärdighet.',
        14: 'Ty om de, som lyda till lagen, äro arfvingar, så är tron onyttig vorden, och löftet är blifvet om intet.',
        15: 'Ty lagen kommer vrede åstad; ty der ingen lag är, der är icke heller öfverträdelse.',
        16: 'Derföre måste det vara af trone, att det skall vara af nåd, och löftet fast blifva allo sädene; icke honom allenast som är af lagen, utan ock honom som är af Abrahams tro, hvilken är allas våra fader;',
        17: 'Som skrifvet är: Jag hafver satt dig till en fader öfver många Hedningar, för Gudi, den du trott hafver, hvilken de döda gör lefvande, och kallar de ting, som icke äro, lika som de voro.',
        18: 'Och han trodde på det hopp, der intet hopp var, att han skulle varda många Hedningars fader, som sagdt var till honom: Så skall din säd vara.',
        19: 'Och han vardt icke svag i trone, och aktade icke sin halfdöda kropp, ty han var när hundrade åra gammal; ej heller Saras halfdöda qved;',
        20: 'Ty han tviflade intet på Guds löfte med otro; utan vardt stark i trone, gifvandes Gudi ärona;',
        21: 'Och var full viss derpå, att den som lofvade, han var ock mägtig det att hålla.',
        22: 'Derföre var det ock räknadt honom till rättfärdighet.',
        23: 'Så är detta icke allenast skrifvet för hans skull, att honom tillräknadt vardt;',
        24: 'Utan ock för våra skull, som det också tillräknadt varder, när vi trom på honom, som vår Herra Jesum uppväckte ifrå de döda;',
        25: 'Hvilken för våra synders skull är utgifven, och för våra rättfärdighets skull uppväckt.',
    },
    5: {
        1: 'Medan vi nu rättfärdige vordne äro af trone, hafve vi frid med Gud, genom vår Herra Jesum Christum;',
        2: 'Genom hvilken vi hafve ock en tillgång i trone till denna nåd, som vi uti ståm, och berömmom oss af hoppet, som vi hafve, till den härlighet som Gud gifva skall.',
        3: 'Och icke det allenast; utan vi berömmom oss ock i bedröfvelsen, vetande att bedröfvelse gör tålamod;',
        4: 'Och tålamod gör förfarenhet; förfarenhet gör hopp;',
        5: 'Men hoppet låter icke komma på skam; ty Guds kärlek är utgjuten i vår hjerta, genom den Helga Anda som oss gifven är.',
        6: 'Ty ock Christus, den stund vi ännu svage vorom efter tiden, hafver lidit döden för oss syndare.',
        7: 'Nu vill näppliga någor dö för det som rätt är; för det som godt är torde tilläfventyrs någor dö.',
        8: 'Derföre beprisar Gud sin kärlek till oss att Christus är död för oss, när vi ännu vore syndare.',
        9: 'Så varde vi ju mycket mer behållne genom honom för vredene, efter vi äre rättfärdige gjorde i hans blod.',
        10: 'Ty efter vi vordom förlikte med Gudi, genom hans Sons död, den stund vi ännu voro ovänner; mycket mer, efter vi äre förlikte, blifve vi nu behållne genom hans lif.',
        11: 'Icke allenast det; utan vi berömmom oss ock af Gudi, genom vår Herra Jesum Christum, genom hvilken vi nu förlikningen fått hafve.',
        12: 'Derföre, såsom igenom ena mennisko är synden kommen i verlden, och för syndenes skull döden; och är så döden kommen öfver alla menniskor, efter de alle syndat hafva,',
        13: 'Ty synden var väl i verldene allt intill lagen; men der ingen lag är, der aktas icke synden;',
        14: 'Utan döden var väldig, allt ifrån Adam intill Mosen, öfver dem ock, som icke hade syndat i sådana öfverträdelse som Adam, hvilken är hans liknelse som tillkommande var.',
        15: 'Men det hafver sig icke så med gåfvone, som med syndene; ty om igenom ens (menniskos) synd äro månge döde, så är mycket mer Guds nåd och gåfva mångom rikeliga vederfaren genom Jesum Christum, som den ena menniskan var i nådene.',
        16: 'Och är icke gåfvan allenast öfver ena synd, såsom förderfvet är kommet fördens ena syndarens ena synd; ty domen är kommen af ene synd till fördömelse, men gåfvan af många synder till rättfärdighet,',
        17: 'Ty om döden hafver, för ens synds skull, väldig varit igenom en; mycket mer skola de, som undfå nådenes och gåfvones fullhet till rättfärdighet, vara väldige i lifvena genom en, Jesum Christum,',
        18: 'Ty såsom för ens synds skull, är fördömelse kommen öfver alla menniskor; så kommer ock, igenom ens rättfärdighet, lifsens rättfärdning öfver alla menniskor.',
        19: 'Ty såsom, för ene menniskos olydno, äro månge vordne syndare; så varda ock, för ens lydnos skull, månge rättfärdige.',
        20: 'Men lagen är också härmed inkommen, att synden skulle öfverflöda; men der synden öfverflödde, der öfverflödde då nåden mycket mer;',
        21: 'På det att, såsom synden hafver väldig varit till döden, så skulle ock nåden väldig vara genom rättfärdighetena till evinnerligit lif, genom Jesum Christum.',
    },
    6: {
        1: 'Hvad vilje vi Då säga? Skole vi blifva i syndene, på det nåden skall öfverflöda?',
        2: 'Bort det; vi som äre döde ifrå syndene, huru skulle vi ännu lefva i henne?',
        3: 'Veten I icke, att alle vi som äre döpte till Christum Jesum, vi äre döpte till hans död?',
        4: 'Så äro vi ju begrafne med honom, genom dopet, i döden; att såsom Christus är uppväckt ifrå de döda, genom Fadrens härlighet, så skole ock vi vandra i ett nytt lefverne.',
        5: 'Ty om vi, samt med honom, inplantade vardom till en lika död, så varde vi ock uppståndelsen like;',
        6: 'Vetande att vår gamla menniska är korsfäst med honom, på det att syndakroppen skall varda om intet, att vi icke härefter skola tjena syndene.',
        7: 'Ty den som döder är, han är rättfärdigad ifrå syndene.',
        8: 'Äre vi nu döde med Christo, så tro vi, att vi ock skole lefva med honom;',
        9: 'Vetande, att Christus, som ifrå de döda uppväckt är, dör intet mer; döden får intet mer magt öfver honom.',
        10: 'Ty det han blef död, blef han syndene död en gång; men det han lefver, lefver han Gudi.',
        11: 'Så håller ock I eder derföre, att I ären döde syndene, och lefven Gudi, genom Christum Jesum, vår Herra.',
        12: 'Så låter nu icke syndena väldig vara i eder dödeliga lekamen, så att I henne efterföljen uti hennes lustar.',
        13: 'Och gifver icke syndene edra lemmar till orättfärdighetenes vapen; utan gifver eder sjelfva Gudi, lika som de der döde hafva varit, och nu lefva; och edra lemmar Gudi, till rättfärdighetenes vapen.',
        14: 'Ty synden skall icke vara väldig öfver eder; efter I ären icke under lagen, utan under nådene.',
        15: 'Huru då? Skole vi synda, medan vi äre icke under lagen, utan under nådene? Bort det.',
        16: 'Veten I icke, att hvem I gifven eder för tjenare till att lyda, hans tjenare ären I, som I lydige ären, ehvad det är mer syndene, till döden, eller lydnone, till rättfärdighetena?',
        17: 'Men lofvad vare Gud, att I hafven varit syndenes tjenare, och ären dock af hjertat lydige vordne, uti den lärdoms eftersyn, som I ären gifne till.',
        18: 'Men nu, medan I ären friade ifrå syndene, ären I rättfärdighetenes tjenare vordne.',
        19: 'Jag talar härom efter menniskors sätt, för edra köttsliga skröplighets skull; lika som I hafven edra lemmar gifvit orenlighet ene och orättfärdighetene till tjenst, ifrå den ena orättfärdighetene till den andra; så gifver ock nu edra lemmar rättfärdighetene till tjenst, att de måga varda helige.',
        20: 'Ty då I voren syndenes tjenare, då voren I frie ifrå rättfärdighetene.',
        21: 'Hvad gagn haden I då af det, der I nu blygens vid? Ty till sådant är döden ändalykten.',
        22: 'Men nu, medan I ären frie vordne ifrå syndene, och vordne Guds tjenare, hafven I edor frukt, att I helige varden; och till ändalykt, evinnerligit lif.',
        23: 'Ty syndenes lön är döden; men Guds gåfva är det eviga lifvet, genom Christum Jesum, vår Herra.',
    },
    7: {
        1: 'Veten I icke, käre bröder (ty jag talar med dem som lagen veta), att lagen regnerar öfver menniskona, så länge hon lefver?',
        2: 'Ty en qvinna, som i mans våld är, så länge mannen lefver, är hon bunden till lagen; men om mannen dör, så blifver hon lös ifrå mansens lag.',
        3: 'Men om hon är med en annan man, medan hennes man lefver, då varder hon kallad en horkona; men dör mannen, så är hon fri ifrå lagen, att hon icke varder en horkona, om hon är när en annan man.',
        4: 'Så ären ock I, mine bröder, dödade ifrå lagen, genom Christi Lekamen; att I skolen vara när enom androm, nämliga när honom som är uppstånden ifrå de döda, på det vi skole göra Gudi frukt.',
        5: 'Ty Då vi vorom köttslige, då voro de syndiga begärelser, som lagen uppväckte, mägtig i våra lemmar, att göra dödenom frukt.',
        6: 'Men nu äre vi friade ifrå lagen, döde ifrå henne som oss höll fångna; så att vi skole tjena uti ett nytt väsende, efter andan, och icke uti det gamla väsendet, efter bokstafven.',
        7: 'Hvad vilje vi då säga? Är lagen synd? Bort det; men syndena kände jag icke, utan af lagen; ty jag hade intet vetat af begärelsen, hade icke lagen sagt: Du skall icke begära.',
        8: 'Då tog synden tillfälle af budordet; och uppväckte i mig all begärelse; ty utan lagen var synden död.',
        9: 'Och jag lefde fordom utan lag; men när budordet kom, fick synden lif igen;',
        10: 'Och jag vardt död; så fanns då, att budordet, som mig var gifvet till lifs, det var mig till döds.',
        11: 'Ty synden tog tillfälle af budordet, och besvek mig, och drap mig dermed.',
        12: 'Så är väl lagen helig, och budordet heligt, och rättfärdigt, och godt.',
        13: 'Är då det, som godt är, vordet mig till döds? Bort det; men synden, på det hon skulle synas vara synd, hafver, med det godt är, verkat döden i mig; på det synen skulle varda öfvermåtton syndig genom budordet.',
        14: 'Ty vi vete, att lagen är andelig; men jag är köttslig, sålder under syndena.',
        15: 'Ty jag vet icke hvad jag gör; ty jag gör icke hvad jag vill; utan det jag hatar, det gör jag.',
        16: 'Om jag nu gör det jag icke vill, så samtycker jag, att lagen är god.',
        17: 'Så gör icke nu jag det, utan synden, som bor i mig.',
        18: 'Ty jag vet, att i mig, det är, i mitt kött, bor icke godt; viljan hafver jag, men att göra godt, det finner jag icke.',
        19: 'Ty det goda, som jag vill, det gör jag intet; utan det onda, som jag icke vill, det gör jag.',
        20: 'Om jag nu gör det jag icke vill, så gör icke nu jag det, utan synden, som bor i mig.',
        21: 'Så finner jag nu mig en lag, jag som vill göra det godt är, att det onda låder vid mig.',
        22: 'Ty jag hafver lust till Guds lag, efter den invärtes menniskona;',
        23: 'Men jag ser en annor lag i mina lemmar, som strider emot den lag, som i min håg är, och griper mig fången uti syndenes lag, som är i mina lemmar.',
        24: 'Jag arme menniska, ho skall lösa mig ifrå denna dödsens kropp?',
        25: 'Gudi tackar jag, genom Jesum Christum, vår Herra. Så tjenar jag nu Guds lag med hågen; men med köttet tjenar jag syndenes lag.',
    },
    8: {
        1: 'Så är nu intet fördömeligit i dem som äro i Christo Jesu, de icke vandra efter köttet, utan efter Andan.',
        2: 'Ty Andans lag, som lif gifver i Christo Jesu, hafver gjort mig fri ifrå syndenes och dödsens lag.',
        3: 'Ty det som lagen icke kunde åstadkomma, i det hon vardt försvagad af köttet, det gjorde Gud, sändandes sin Son i syndelig kötts liknelse, och fördömde syndena i köttet genom synd;',
        4: 'På det den rättfärdighet, som lagen äskar, skulle varda fullbordad i oss, som icke vandrom efter köttet, utan efter Andan.',
        5: 'Ty de som köttslige äro, de äro köttsliga sinnade; men de som andelige äro, de äro andeliga sinnade.',
        6: 'Ty köttsens sinne är döden; men Andans sinne är lif och frid.',
        7: 'Ty köttsligit sinne är en fiendskap emot Gud; efter det är icke Guds lag underdånigt; icke kan det heller.',
        8: 'Men de, som äro köttslige, kunna icke vara Gudi täcke.',
        9: 'Men I ären icke köttslige, utan andelige, om Guds Ande annars bor i eder; ty hvilken icke hafver Christi Anda, han hörer icke honom till.',
        10: 'Men om Christus är i eder, så är väl lekamenen död, för syndenes skull; men Anden är lifvet, för rättfärdighetenes skull.',
        11: 'Om nu hans Ande, som Jesum uppväckte ifrå de döda, bor i eder, så skall ock den, som Christum uppväckte ifrå de döda, göra edor dödeliga lekamen lefvande, för sin Andas skull, som i eder bor.',
        12: 'Så äre vi nu, käre bröder, skyldige, icke köttena, att vi skole lefva efter köttet;',
        13: 'Ty om I lefven efter köttet, så skolen I dö; men om I döden köttsens gerningar med Andanom, så skolen I lefva.',
        14: 'Ty alle de som drifvas af Guds Anda, de äro Guds barn.',
        15: 'Ty I hafven icke fått träldomsens anda, åter till räddhåga; utan I hafven fått utkorada barns Anda, i hvilkom vi rope: Abba, käre Fader.',
        16: 'Den samme Anden vittnar med vår Anda, att vi äre Guds barn.',
        17: 'Äre vi nu barn, så äre vi ock arfvingar; nämliga Guds arfvingar, och Christi medarfvingar; om vi annars lidom med honom, att vi ock med honom komma mågom till härligheten.',
        18: 'Ty jag håller det så före, att denna tidsens vedermöda är icke lika emot den härlighet, som på oss uppenbaras skall.',
        19: 'Ty kreaturens högeliga åstundan väntar efter, att Guds barn skola uppenbaras;',
        20: 'Efter kreaturen äro vanskelighetene underkastade emot sin vilja; men för hans skull, som dem underkastat hafver, på en förhoppning.',
        21: 'Ty kreaturen skola ock varda fri af förgängelighetenes träldom, till Guds barnas härliga frihet.',
        22: 'Ty vi vete, att hvart och ett kreatur suckar och ängslas med oss, allt härtill.',
        23: 'Och icke de allenast; utan ock vi sjelfve, som hafvom Andans förstling, suckom ock vid oss sjelfva efter barnaskapet, och väntom vår kropps förlossning.',
        24: 'Ty vi äre väl salige vordne, dock i hoppet; men hoppet, om det synes, är det icke hopp; ty huru kan man hoppas det man ser?',
        25: 'Om vi nu hoppes det vi icke sem, så vänte vi det med tålamod.',
        26: 'Sammaledes hjelper ock Anden våra skröplighet; ty vi vete icke hvad vi skolom bedja, såsom det bör sig; utan sjelfver Anden manar godt för oss, med osägeliga suckan.',
        27: 'Men han, som skådar hjertan, han vet hvad Andans sinne är; ty han manar för helgonen, efter Guds behag.',
        28: 'Men vi vete att dem, som hafva Gud kär, tjena all ting till det bästa, de som efter uppsåtet äro kallade.',
        29: 'Ty hvilka han hafver föresett, dem hafver han ock beskärt, att de skulle vara hans Sons beläte like; på det han skall vara den förstfödde ibland många bröder.',
        30: 'Men dem som han hafver beskärt, dem hafver han ock kallat; och dem han hafver kallat, dem hafver han ock gjort rättfärdiga; men dem som han hafver gjort rättfärdiga, dem hafver han ock gjort härliga.',
        31: 'Hvad vilje vi nu säga härtill? Är Gud för oss, ho kan vara emot oss?',
        32: 'Hvilken ock icke hafver skonat sin egen Son, utan gifvit honom ut för oss alla; huru skulle han icke ock gifva oss all ting med honom?',
        33: 'Hvilken vill åklaga dem som Gud hafver utkorat? Gud är den som rättfärdigar.',
        34: 'Hvilken är den som vill fördöma? Christus är den som lidit hafver döden; ja, han är ock den som uppväckt är; den ock sitter på Guds högra hand, och manar godt för oss.',
        35: 'Ho kan skilja oss ifrå Christi kärlek? Bedröfvelse, eller ångest, eller förföljelse, eller hunger, eller nakenhet, eller farlighet, eller svärd?',
        36: 'Såsom skrifvet är: För dina skull vardom vi dödade hela dagen; vi vardom hållne såsom slagtofår.',
        37: 'Men i allt detta öfvervinne vi, genom honom som oss älskat hafver.',
        38: 'Ty jag är viss derpå, att hvarken död, eller lif, eller Änglar, eller Förstadöme, eller väldigheter, eller de ting som nu äro, eller de ting som tillkomma skola;',
        39: 'Eller höghet, eller djuphet, eller något annat kreatur, skall skilja oss ifrå Guds kärlek, som är i Christo Jesu, vårom Herra.',
    },
    9: {
        1: 'Jag säger sanningen i Christo, och ljuger icke; som mitt samvete bär mig der vittne till i dem Helga Anda;',
        2: 'Att jag hafver ena stora sorg, och idkeliga pino i mitt hjerta.',
        3: 'Ty jag hafver sjelfver önskat mig bortkastad ifrå Christo, för mina bröders skull, som mig köttsliga skylde äro;',
        4: 'Hvilke äro af Israel, hvilkom barnaskapet tillhörer, och härligheten, och förbundet, och lagen, och Gudstjensten, och löften;',
        5: 'Hvilkas äro fäderna, der Christus af födder är, på köttsens vägnar; hvilken är Gud öfver all ting, lofvad evinnerliga. Amen.',
        6: 'Detta säger jag icke fördenskull, att Guds ord äro omintet vorden; ty de äro icke alle Israeliter, som äro af Israel;',
        7: 'Icke äro de heller alle söner, att de äro Abrahams säd; utan i Isaac skall dig kallas säden;',
        8: 'Det är: Icke äro de Guds barn, som äro barn efter köttet, utan de som äro barn efter löftet, de varda räknade för säd.',
        9: 'Ty detta är löftesordet: Jag skall komma i denna tiden; och Sara skall hafva en son.',
        10: 'Och icke allenast det; utan ock Rebecka vardt en gång hafvandes af Isaac, vårom fader.',
        11: 'Ty förr än barnen voro född, och hade hvarken godt eller ondt gjort (på det Guds uppsåt skulle blifva ståndandes efter utkorelsen, icke för gerningarnas skull, utan af kallarens nåde),',
        12: 'Vardt denne sagdt: Den större skall tjena dem mindre;',
        13: 'Såsom skrifvet är: Jacob älskade jag men Esau hatade jag.',
        14: 'Hvad vilje vi då säga? Är Gud orättfärdig? Bort det.',
        15: 'Ty han säger till Mosen: Hvilkom jag är nådelig, honom är jag nådelig; och öfver hvilken jag förbarmar mig, öfver honom förbarmar jag mig.',
        16: 'Så står det nu icke till någors mans vilja eller lopp, utan till Guds barmhertighet.',
        17: 'Ty Skriften säger till Pharao: Dertill hafver jag uppväckt dig, att jag skall bevisa mina magt på dig; och att mitt Namn skall varda förkunnadt i all land.',
        18: 'Så förbarmar han nu sig öfver hvem han vill, och hvem han vill, förhärdar han.',
        19: 'Så må du säga till mig: Hvad skyllar han då oss? Ho kan stå emot hans vilja?',
        20: 'O menniska, ho äst du som vill träta med Gud? Icke säger det ting, som gjordt är, till sin mästare: Hvi hafver du gjort mig sådana?',
        21: 'Hafver icke en pottomakare magt att göra af en klimp ett kar till heder, och det andra till vanheder?',
        22: 'Derföre, då Gud ville låta se vredena, och kungöra sina magt, hafver han med stor tålsamhet lidit vredsens kar, som äro tillredd till fördömelse;',
        23: 'På det han skulle kungöra sina härlighets rikedom på barmhertighetenes kar, som han hafver tillredt till härlighet;',
        24: 'Hvilka han ock kallat hafver, nämliga oss, icke allenast af Judomen, utan ock af Hedningomen;',
        25: 'Såsom han ock säger genom Oseas: Det som icke var mitt folk, det skall jag kalla mitt folk; och den mig intet kär var, skall jag kalla min kära.',
        26: 'Och det skall ske, att der som hafver varit sagdt till dem: I ären icke mitt folk; der skola de varda kallade lefvandes Guds barn.',
        27: 'Men Esaias ropar för Israel: Om talet på Israels barn än vore som sanden i hafvet, så skola dock de igenlefde varda salige.',
        28: 'Ty han skall väl låta förderfva dem, och dock likväl stilla det förderfvet till rättfärdighet; ty Herren skall stilla förderfvet på jordene.',
        29: 'Och såsom Esaias sade tillförene: Hade icke Herren Zebaoth igenleft oss säd, då hade vi varit såsom Sodoma, och lika som Gomorra.',
        30: 'Hvad vilje vi då säga? Det säge vi: Hedningarna, som icke farit hafva efter rättfärdighetene, de hafva fått rättfärdigheten; den rättfärdighet menar jag, som af trone kommer.',
        31: 'Men Israel, som for efter rättfärdighetenes lag, kom icke till rättfärdighetenes lag.',
        32: 'Hvarföre? Derföre att de icke sökte det af trone, utan såsom af lagsens gerningar; ty de stötte sig på förtörnelsestenen;',
        33: 'Såsom skrifvet är: Si, jag lägger i Zion en förtörnelsesten, och ena förargelseklippo: och hvar och en som tror på honom, skall icke komma på skam.',
    },
    10: {
        1: 'Bröder, mins hjertas begär och bön till Gud är för Israel, att de måtte varda salige;',
        2: 'Ty jag bär vittne med dem, att de hafva nit om Gud; dock icke visliga.',
        3: 'Ty de förstå icke Guds rättfärdighet; utan fara efter att upprätta sin egen rättfärdighet, och äro så icke Guds rättfärdighet undergifne.',
        4: 'Ty Christus är lagsens ände, till rättfärdighet hvarjom och enom som tror.',
        5: 'Moses skrifver om den rättfärdighet som kommer af lagen, att hvilken menniska som det gör, hon lefver deruti.',
        6: 'Men den rättfärdighet, som är af trone, säger så: Säg icke i ditt hjerta: Ho vill fara upp i himmelen? Det är, att hemta Christum härned.',
        7: 'Eller, ho vill fara ned i djupet? Det är, att hemta Christum upp igen ifrån de döda.',
        8: 'Men hvad säger (Skriften)? Ordet är hardt när dig, nämliga i dinom mun, och i ditt hjerta. Detta är det ordet om trona, som vi predikom.',
        9: 'Ty om du bekänner med dinom mun Jesum, att han är Herren, och tror i ditt hjerta att Gud hafver uppväckt honom ifrå de döda, så varder du salig.',
        10: 'Ty med hjertans tro varder man rättfärdig, och med munsens bekännelse varder man salig.',
        11: 'Ty Skriften säger: Hvar och en, som tror på honom, skall icke komma på skam.',
        12: 'Det är ingen åtskilnad emellan Juda och Grek; ty en Herre är öfver alla, riker öfver alla dem som åkalla honom.',
        13: 'Ty hvar och en, som åkallar Herrans namn, skall varda salig.',
        14: 'Men huru skola de åkalla den de hafva icke trott på? Och huru skola de tro honom, som de hafva intet hört af? Och huru skola de höra utan predikare?',
        15: 'Och huru skola de predika, utan de varda sände? såsom skrifvet är: O! huru ljuflige äro deras fötter, som frid förkunna, deras som godt förkunna.',
        16: 'Men de äro icke alle Evangelio lydige; ty Esaias säger: Herre, ho tror vår predikan?',
        17: 'Så är tron af predikanen; men predikanen genom Guds ord.',
        18: 'Så säger jag nu: Hafva de icke hört det? Deras ljud är ju utgånget i all land, och deras ord till verldenes ändar.',
        19: 'Men jag säger: Hafver då Israel det icke fått veta? Den förste Moses säger: Jag skall uppväcka eder till nit med det folk, som icke är folk; och med ett galet folk skall jag reta eder.',
        20: 'Dristar ock Esaias sig till, och säger: Jag är funnen af dem, som intet sökte mig, och är vorden uppenbar dem, som intet sporde efter mig.',
        21: 'Men till Israel säger han: Hela dagen hafver jag uträckt mina händer till det otrogna och genstörtiga folket.',
    },
    11: {
        1: 'Så säger jag nu: Hafver Då Gud bortkastat sitt folk? Bort det; ty jag är ock en Israelit, af Abrahams säd, af BenJamins slägte.',
        2: 'Gud hafver icke bortkastat sitt folk, som han hade föresett tillförene. Eller veten I icke hvad Skriften säger om Elias? huru han går fram för Gud emot Israel, och säger:',
        3: 'Herre, de hafva dräpit dina Propheter, och hafva slagit ned din altare; och jag är allena igenblifven, och de fara efter mitt lif.',
        4: 'Men hvad säger honom Guds svar? Jag hafver mig igenleft sjutusend män, som icke hafva böjt sin knä för Baal.',
        5: 'Så är det ock i denna tiden med de igenlefda, efter nådenes utkorelse.',
        6: 'Är det nu af nåd, så är det icke af gerningom; annars vore nåd icke nåd; är det ock af gerningom, så är det nu icke nåd; annars är gerning icke gerning.',
        7: 'Huru äret då? Det Israel söker, det får han icke; men utkorelsen får det; de andre äro förblindade;',
        8: 'Såsom skrifvet är: Gud hafver gifvit dem en förbittrad anda; ögon, att de icke se skola, och öron, att de icke höra skola allt härtilldags.',
        9: 'Och David säger: Låt deras bord varda en snaro, och till bekajelse, och till förargelse, och dem till deras rätta lön.',
        10: 'Varde deras ögon förblindad, att de icke se; och böj deras rygg alltid.',
        11: 'Så säger jag nu: Hafva de då fördenskull stött sig, att de skulle falla? Bort det; men af deras fall hände Hedningomen salighet, på det att han dermed skulle uppväcka dem till nit.',
        12: 'Är nu deras fall verldenes rikedom, och deras förminskelse är Hedningarnas rikedom; huru mycket mer deras fullhet?',
        13: 'Eder Hedningomen säger jag: Efter det jag är Hedningarnas Apostel, prisar jag mitt ämbete;',
        14: 'Om jag kunde någorledes uppväcka dem, som mitt kött äro, till nit, och göra några saliga af dem.',
        15: 'Ty om deras bortkastelse är verldenes försoning, hvad blifver Då deras upptagelse annat än lif ifrå de döda?',
        16: 'Är förstlingen helig, så är ock väl hele degen helig och om roten är helig, så äro ock qvistarna helige.',
        17: 'Om nu någre af qvistarna äro afbrutne, och du, som var ett vildoljoträ, blef der inympad igen, och äst vorden delaktig af oljoträns rot och fetma;',
        18: 'Så beröm dig icke emot qvistarna. Om du berömmer dig, så bär ju icke du rotena, utan roten bär dig.',
        19: 'Så säger du då: Qvistarna äro afbrutne, på det jag skulle inympas.',
        20: 'Sant säger du; de äro afbrutne för otrones skull; men du äst ståndandes genom trona; var icke för stolt i ditt sinne, utan var i räddhåga.',
        21: 'Ty hafver Gud de naturliga qvistar icke skonat, se till, att han icke heller skonar dig.',
        22: 'Så se nu här Guds godhet och stränghet; strängheten på dem som föllo, och godheten på dig, så framt du blifver i godhetene; annars varder du ock afhuggen;',
        23: 'Och de inympas igen, om de icke blifva i otrone; ty Gud är mägtig åter inympa dem.',
        24: 'Ty äst du af ett naturligit vildoljoträ afhuggen, och förutan naturen inympad uti ett sannskyldigt oljoträ; huru mycket mer måga de, som naturlige qvistar äro, inympas uti sitt eget oljoträ?',
        25: 'Käre bröder, jag vill icke fördölja eder denna hemlighet, på det I icke skolen högmodas vid eder sjelfva, att blindheten är Israel endels vederfaren, tilldess Hedningarnas fullhet inkommen är;',
        26: 'Och så varder hele Israel salig; såsom skrifvet är: Af Zion skall den komma som fria skall, och afvända ogudaktigheten af Jacob.',
        27: 'Och detta är mitt Testament med dem, då jag borttager deras synder.',
        28: 'Efter Evangelium håller jag dem för ovänner, för edra skull; men efter utkorelsen hafver jag dem kär, för fädernas skull.',
        29: 'Ty Guds gåfvor och kallelse äro sådana, att han kan dem icke ångra.',
        30: 'Ty såsom ock I fordom icke trodden på Gud, och hafven dock nu öfver deras otro fått barmhertighet;',
        31: 'Så hafva ock nu de icke velat tro på den barmhertighet, som eder vederfaren är, att dem måtte ock barmhertighet vederfaras.',
        32: 'Ty Gud hafver allt beslutit under otro, på det han skall förbarma sig öfver alla.',
        33: 'O! hvilken djuphet af den rikedom, som är både i Guds visdom och kunskap; huru obegripelige äro hans domar, och oransakelige hans vägar.',
        34: 'Ty ho hafver känt Herrans sinne? Eller ho hafver varit hans rådgifvare?',
        35: 'Eller ho hafver gifvit honom något tillförene, det honom skall betaladt varda?',
        36: 'Ty af honom, och igenom honom, och i honom äro all ting; honom vare ära i evighet. Amen.',
    },
    12: {
        1: 'Så förmanar jag nu eder, käre bröder, vid Guds barmhertighet, att I utgifven edor lekamen till ett offer, som är lefvande, heligt och Gudi behageligit, edra skäliga Gudstjenst.',
        2: 'Och håller eder icke efter denna verldena; utan förvandler eder med edars sinnes förnyelse, att I mågen förfara hvad Guds gode, behaglige och fullkomlige vilje är.',
        3: 'Ty jag säger, igenom den nåd som mig gifven är, hvarjom och enom af eder, att ingen hålle mer af sig, än honom bör hålla; utan hålle sig så, att der är måtta med, efter som Gud hafver utdelat hvarjom och enom trones mått.',
        4: 'Ty såsom vi uti en lekamen hafve många lemmar, men alle lemmar hafva icke allt samma ämbete;',
        5: 'Så äre vi nu månge en lekamen i Christo, men inbördes äre vi hvarsannars lemmar;',
        6: 'Och hafve åtskilliga gåfvor, efter den nåd som oss gifven är. Hafver någor Prophetiam, så vare hon ens med trone.',
        7: 'Hafver någor ett ämbete, så akte han derpå; lärer någor, så akte han på lärona.',
        8: 'Förmanar någor, så akte han på förmaningen; gifver någor, så gifve uti enfaldighet; regerar någor, så regere med omsorg; gör någor barmhertighet, så göre det med fröjd.',
        9: 'Kärleken vare utan skrymtan; hater det onda, blifvandes vid det godt är.',
        10: 'Varer hvar med annan vänlige, uti broderlig kärlek; den ene förekomme den andra med inbördes heder.',
        11: 'Varer icke tröge uti det I hafven för händer; varer brinnande i Andanom; skicker eder efter tiden.',
        12: 'Varer glade i hoppet; tålige i bedröfvelse; håller på bedja.',
        13: 'Deler edart till de heligas nödtorft; herberger gerna.',
        14: 'Taler väl om dem som gå efter edart argasta; taler väl, och önsker dem icke ondt.',
        15: 'Glädjens med dem som glade äro; och gråter med dem som gråta.',
        16: 'Ens till sinnes med hvarannan; håller icke mycket af eder sjelfva; utan håller eder lika vid dem som ringa äro; håller eder icke sjelfva för kloka,',
        17: 'Görer ingom ondt för ondt; vinnlägger eder om det som ärligit är, inför hvar man.',
        18: 'Om möjeligit är, så mycket som till eder står, så hafver frid med alla menniskor.',
        19: 'Hämnens eder icke sjelfve, käre vänner; utan låter (Guds) vrede hafva rum; ty det är skrifvet: Min är hämnden, jag skall vedergällat, säger Herren.',
        20: 'Om nu din ovän hungrar, så gif honom mat; törster han, så gif honom dricka; när du det gör, så församlar du glödande kol på hans hufvud.',
        21: 'Låt dig icke öfvervunnen varda af det onda; utan öfvervinn det onda med det goda.',
    },
    13: {
        1: 'Hvar och en vare Öfverhetene, som väldet hafver, underdånig; ty ingen Öfverhet är, utan af Gudi; den Öfverhet, som är, hon är skickad af Gudi.',
        2: 'Derföre, ho sig sätter emot Öfverheten, han sätter sig emot Guds skickelse; men de som sätta sig deremot, de skola få en dom öfver sig.',
        3: 'Ty de, som väldet hafva, äro icke dem till räddhåga som väl göra, utan dem som illa göra. Vill du icke frukta för Öfverheten, så gör det godt är, så får du pris af honom;',
        4: 'Ty han är Guds tjenare, dig till godo. Men gör du det ondt är, så må du rädas; ty han bär icke svärdet förgäfves; utan han är Guds tjenare, en nämnare honom till straff, som illa gör.',
        5: 'Fördenskull måste man vara underdånig, icke allenast för straffets skull, utan ock för samvetets skull.',
        6: 'Derföre måsten I ock gifva skatt; ty de äro Guds tjenare, som sådant skola sköta.',
        7: 'Så gifver nu hvarjom och enom det I pligtige ären; dem skatt, som skatt bör; dem tull, som tull bör; dem rädsel, som rädsel tillhörer; dem heder, som heder tillhörer.',
        8: 'Varer ingom något skyldige, utan att I älskens inbördes; ty den som älskar den andra, han hafver fullbordat lagen.',
        9: 'Ty det som sagdt är: Du skall icke göra hor; du skall icke dräpa; du skall icke stjäla; du skall icke bära falskt vittne; du skall icke begära; och annat sådant bud, det beslutes i detta ordet: Du skall älska din nästa som dig sjelf.',
        10: 'Kärleken gör sin nästa intet ondt. Så är nu kärleken lagsens fullbordan.',
        11: 'Och medan vi sådant vete, nämliga tiden, att nu är stunden till att uppstå af sömnen, efter vår salighet är nu närmer, än då vi troddet;',
        12: 'Natten är framfaren, och dagen är kommen; derföre låter oss bortkasta mörksens gerningar, och ikläda oss ljusens vapen:',
        13: 'Låter oss ärliga vandra, såsom om dagen; icke i fråsseri och dryckenskap; icke i kamrar och okyskhet; icke i kif och nit;',
        14: 'Utan ikläder eder Herran Jesum Christum; och fordrer köttet, dock icke till kättja.',
    },
    14: {
        1: 'Den svaga i trone tager upp; och bekymrer icke samvetet.',
        2: 'Den ene tror, att han må allahanda äta; men den som svag är, han äter kål.',
        3: 'Den der äter, han förakte icke honom som icke äter, och den som icke äter, han döme icke honom som äter; ty Gud hafver honom upptagit.',
        4: 'Ho äst du, som dömer en annars tjenare? Sinom egnom herra står han eller faller; men han kan väl varda ståndandes; ty Gud är väl mägtig till att göra honom ståndandes.',
        5: 'Den ene gör åtskilnad emellan dag och dag; den andre håller alla dagar lika; hvar och en vare viss i sitt sinne.',
        6: 'Hvilken som aktar någon dag, det gör han Herranom; och hvilken icke aktar någon dag, han gör det ock Herranom. Hvilken som äter, han äter Herranom; ty han tackar Gudi. Den der icke äter, han icke äter Herranom, och tackar Gudi.',
        7: 'Ty ingen af oss lefver sig sjelfvom; och ingen dör sig sjelfvom.',
        8: 'Lefve vi, så lefve vi Herranom; dö vi, så dö vi Herranom; ehvad vi nu lefve eller dö, så höre vi Herranom till.',
        9: 'Ty Christus är derpå både död och uppstånden, och åter lefvandes vorden, att han skall vara Herre, både öfver lefvande och döda.',
        10: 'Men du, hvi dömer du din broder? Eller du andre, hvi föraktar du din broder? Ty vi måste alle stå framför Christi domstol;',
        11: 'Såsom skrifvet står: Så sant som jag lefver, säger Herren, mig skola all knä böjas; och alla tungor skola bekänna Gud.',
        12: 'Så måste nu hvar och en af oss göra Gudi räkenskap för sig sjelf.',
        13: 'Derföre, låt oss nu icke mera döma hvarannan; utan dömer heldre så, att ingen förtörnar sin broder, eller förargar.',
        14: 'Jag vet väl, och är dess viss i Herranom Jesu, att ingen ting äro af sig sjelf menlig; utan den som håller det för menligit, honom är det menligit.',
        15: 'Dock, om din broder varder bedröfvad öfver din mat, så vandrar du allaredo icke efter kärleken. Förderfva icke, med din mat, den som Christus hafver lidit döden före.',
        16: 'Derföre flyr det så, att edart goda icke varder undergifvet menniskors förtal.',
        17: 'Ty Guds rike är icke mat eller dryck, utan rättfärdighet, och frid, och fröjd i dem Helga Anda.',
        18: 'Den der uti tjenar Christo, han är Gudi täck, och menniskomen bepröfvad.',
        19: 'Så låt oss nu fara efter det som till frids tjenar, och det som tjenar till förbättring inbördes.',
        20: 'Förderfva icke, för mats skull, Guds verk. All ting äro väl ren; men honom är det icke godt, som äter med sitt samvets förkränkelse.',
        21: 'Godt är dig, att du äter intet kött, eller dricker intet vin; ej heller något der din broder stöter sig på, eller förargas, eller försvagas.',
        22: 'Hafver du tron, så haf henne när dig sjelf för Gudi. Salig är den som sig intet samvet gör, om det han bepröfvar.',
        23: 'Men den som tvifvelaktig är, äter han, så är han fördömd; ty han äter icke af tron; ty allt det icke går af trone, det är synd.',
    },
    15: {
        1: 'Skole ock vi, som starke äre, draga deras skröplighet, som svage äro, och icke täckas oss sjelfvom.',
        2: 'Så skicke sig hvar och en af oss, att han måtte täckas sin nästa till godo, till förbättring.',
        3: 'Ty ock Christus täcktes icke sig sjelfvom; utan såsom skrifvet står: Deras försmädelser, som dig försmäda, hafva fallit öfver mig.',
        4: 'Ty hvad som helst föreskrifvet är, det är skrifvet oss till lärdom; att vi, genom tålamod och Skriftenes tröst, skole hafva en förhoppning.',
        5: 'Men Gud, som tålamod och trösten gifver, gifve eder, att I ären inbördes ens till sinnes, efter Christum Jesum;',
        6: 'Att I med enom håg, och med enom mun, mågen prisa Gud, och vårs Herras Jesu Christi Fader.',
        7: 'Derföre upptager hvar den andra, såsom ock Christus hafver upptagit oss till Guds äro.',
        8: 'Men jag säger, att Jesus Christus var omskärelsens tjenare, för Guds sannings skull, till att fast göra de löften, som till fäderna skedde;',
        9: 'Men att Hedningarna skola ära Gud, för barmhertighetenes skull; såsom skrifvet är: Fördenskull skall jag prisa dig ibland Hedningarna, och sjunga dino Namne.',
        10: 'Och åter säger han: Glädjens, I Hedningar, med hans folk;',
        11: 'Och ändå sedan: Lofver Herran, alle Hedningar, och priser honom, all folk.',
        12: 'Och åter säger Esaias: Det skall vara Jesse rot, och den som uppstå skall att råda öfver Hedningarna; på honom skola Hedningarna hoppas.',
        13: 'Men Gud, som hoppet gifver, uppfylle eder med alla fröjd och frid i trone, att I hafven ett fullkommeligit hopp, genom dens Helga Andas kraft.',
        14: 'Mine bröder, jag vet väl sjelf af eder, att I ären fulle af godhet, uppfyllde med all kunskap, förmående förmana hvar den andra.',
        15: 'Dock likväl, bröder, hafver jag skrifvit eder endels dristeliga till, att kommat eder till sinnes, för den nåds skull, som mig gifven är af Gudi;',
        16: 'Att jag skall vara Jesu Christi tjenare ibland Hedningarna, offrandes Guds Evangelium; att Hedningarne skola varda ett offer, Gudi anammeligit, helgadt genom den Helga Anda.',
        17: 'Derföre hafver jag, der jag må berömma mig af, igenom Christum Jesum, i det Gudi tillhörer.',
        18: 'Ty jag dristar icke något tala, det icke Christus verkade igenom mig, till att göra Hedningarna lydaktiga, genom ord och gerningar;',
        19: 'Genom teckens och unders kraft, och genom Guds Andas kraft; så att ifrån Jerusalem, och de land deromkring ligga, allt intill Illyricum, hafver jag uppfyllt med Christi Evangelium;',
        20: 'Och beflitat mig att predika Evangelium, der Christus icke ens hade varit nämnd, på det jag icke skulle bygga på ens annars grund;',
        21: 'Utan, såsom skrifvet står: Dem som intet hafver kungjordt varit om honom, de skola det se; och de som af honom intet hört hafva, de skola det förstå.',
        22: 'Det är ock saken, hvarföre jag ofta hafver varit förhindrad att komma till eder.',
        23: 'Nu, efter jag icke mer rum hafver i dessa landen, och hafver dock i mång år åstundat komma till eder;',
        24: 'Då jag reser ut i Hispanien, vill jag komma till eder; ty jag hoppas att, då jag reser derigenom, skall jag få se eder, och sedan varda af eder hulpen dit att komma; dock att jag ju först någon lust hafver haft af edor umgängelse.',
        25: 'Men nu far jag hädan till Jerusalem, till att göra dem heligom tjenst.',
        26: 'Ty de som bo uti Macedonien, och Achajen, hafva belefvat göra någon undsättning dem fattigom heligom, som äro i Jerusalem.',
        27: 'Ty de hafva så belefvat, och äro dem ock pligtige; fördenskull, att efter de hafva delat med Hedningarna sin andeliga ting, är tillbörligit, att de äro dem till tjenst med deras lekamliga ting.',
        28: 'Då jag nu beställt hafver, och förseglat dem denna frukt, vill jag komma tillbaka igen, och genom edar (stad) fara till Hispanien.',
        29: 'Men jag vet, när jag kommer till eder, varder jag kommandes med Christi Evangelii fullkomliga välsignelse.',
        30: 'Men, käre bröder, jag förmanar eder genom vår Herra Jesum Christum, och igenom Andans kärlek, att I mig uti mitt arbete hjelpen, med edra böner för mig till Gud;',
        31: 'Att jag må frälst varda ifrå de otrogna i Judeen; och att min tjenst, som jag gör i Jerusalem, må anammelig varda dem heligom;',
        32: 'Att jag må med glädje komma till eder, genom Guds vilja, och vederqvicka mig med eder.',
        33: 'Men fridsens Gud vare med eder allom. Amen.',
    },
    16: {
        1: 'Jag befaller eder våra syster Phebe, hvilken är i församlingenes tjenst i Kenchrea.',
        2: 'Att I henne undfången i Herranom, såsom helgon höfves; och görer henne bistånd i all ärende, der hon eder behöfver; ty hon hafver mångom, och jemväl mig sjelfvom, varit till godo.',
        3: 'Helser Priscilla, och Aqvila, mina hjelpare i Christo Jesu;',
        4: 'Hvilke för mitt lif hafva vågat sin hals; dem tackar icke allenast jag, utan ock alla Hedningars församlingar.',
        5: 'Helser ock församlingena i deras hus; helser Epenetus, min älskeliga, hvilken var den första frukt i Achajen, i Christo.',
        6: 'Helser Maria, den der mycket arbete för oss haft hafver.',
        7: 'Helser Andronicus, och Junia, mina fränder och medfångar, de der märkelige äro ibland Apostlarna; de der ock för mig voro i Christo.',
        8: 'Helser Amplia, min älskeliga i Herranom.',
        9: 'Helser Urbanus, vår hjelpare i Christo, och Stachis, min älskeliga.',
        10: 'Helser Apellen, den der bepröfvad är i Christo; helser dem som äro af Aristobuli hus.',
        11: 'Helser Herodion, min frända; helser dem som äro af Narcissi hus, i Herranom.',
        12: 'Helser Tryphena och Tryphosa, de der arbeta i Herranom; helser Persiden, mina älskeliga, som mycket arbetat hafver i Herranom.',
        13: 'Helser Rufum, den utkorada i Herranom; och hans moder, och mina.',
        14: 'Helser Asyncritum, Phlegontem, Herman, Patroban, Hermen, och de bröder som med dem äro.',
        15: 'Helser Philologum, och Julian, Nereum, och hans syster, och Olympan, och all helgon när dem.',
        16: 'Helser eder inbördes med en helig kyss; helsa eder Christi församlingar.',
        17: 'Käre bröder, jag förmanar eder, att I hafven uppseende på dem, som tvist och förargelse åstadkomma, emot den lärdom som I hafven lärt; och viker ifrå dem.',
        18: 'Ty sådane tjena icke Herranom Jesu Christo, utan sinom buk; och igenom söt ord och smekande tal förföra deras hjerta, som menlöse äro.',
        19: 'Ty edar lydaktighet är utkommen till hvar man. Derföre fröjdar jag mig öfver eder; men jag vill, att I ären vise på det goda, och enfaldige på det onda.',
        20: 'Men fridsens Gud förträde Satanam under edra fötter snarliga. Vårs Herras Jesu Christi nåd vare med eder. Amen.',
        21: 'Helsar eder Timotheus, min medhjelpare, och Lucius, och Jason, och Sosipater, mine fränder;',
        22: 'Helsar jag Tertius eder, som brefvet skrifvit hafver, i Herranom.',
        23: 'Helsar eder Gajus, min och hela församlingenes värd; helsar eder Erastus, stadsens räntomästare, och Qvartus, brodren.',
        24: 'Vårs Herras Jesu Christi nåd vare med eder allom. Amen.',
        25: 'Men honom, som magt hafver att stadfästa eder, efter mitt Evangelium, och predikan af Jesu Christo, efter hemlighetenes uppenbarelse, den af evig tid härtill hafver förtegad varit;',
        26: 'Men nu uppenbarad och kungjord, igenom Propheternas skrifter, af eviga Guds befallning; på det tron skall få lydaktighet ibland alla Hedningar;',
        27: 'Gudi, som är allena vis, vare pris och ära, genom Jesum Christum, i evighet. Amen. Till de Romare, sänd ifrå Corintho, med Phebe, som i församlingenes tjenst var i Kenchrea.',
    },
}
